insert into public.site_settings (key, label, value, is_public, sort_order) values ('overview_body', 'Overview paragraphs (one per line)', '["The Department of English at Dr. Babasaheb Ambedkar Open University offers programmes in English language and literature designed for the open and distance learner — the working professional, the homemaker, the first-generation graduate and the lifelong reader alike.","Our curriculum, shaped by NEP 2020, reads British, American and world literatures alongside Indian Writing in English, translation, and the living traditions of Indian Knowledge Systems. Self-Learning Material, video lectures and the department''s Smart SLM (SSLM) initiative let learners study at their own pace without losing the rigour of a university classroom.","Whether you are preparing for UGC NET, a teaching career, translation and publishing, or simply returning to the books you love, the department is here to guide your reading."]'::jsonb, true, 110)
