insert into public.site_settings (key, label, value, is_public, sort_order) values ('programme_quiz', '“Which programme suits me?” quiz (advanced: JSON)', '{"intro":"Three quick questions to suggest where to begin. It is only a suggestion — always check the eligibility on the programme''s page.","questions":[{"q":"What have you completed so far?","options":[{"label":"Class 12 (Higher Secondary) or equivalent","scores":{"ba":3,"certificate":1}},{"label":"A bachelor''s degree","scores":{"ma":3,"diploma":2,"certificate":1}},{"label":"A master''s degree","scores":{"phd":3,"diploma":1,"certificate":1}}]},{"q":"What would you like next?","options":[{"label":"A full degree","scores":{"ba":2,"ma":2}},{"label":"A short, focused course","scores":{"certificate":3,"diploma":1}},{"label":"Deeper specialisation","scores":{"diploma":2,"ma":1}},{"label":"Research","scores":{"phd":3}}]},{"q":"How much time can you give?","options":[{"label":"A few months","scores":{"certificate":2}},{"label":"About a year","scores":{"diploma":2}},{"label":"Two years or more","scores":{"ba":1,"ma":1,"phd":1}}]}]}'::jsonb, true, 250)
