insert into public.sections (slug, title, title_gu, kicker, intro, intro_gu, body, renderer, sort_order, published) values ('slm', 'SLM & Study Material', 'એસ.એલ.એમ. અને અભ્યાસ સામગ્રી', 'Folio III', 'Self-Learning Material, study material and assignments — find yours by programme, semester or course.', 'તમારા અભ્યાસક્રમ, સત્ર કે કોર્સ મુજબ સ્વ-અધ્યયન સામગ્રી અને સ્વાધ્યાય શોધો.', '{}'::text[], 'slm', 30, true)
