insert into public.sections (slug, title, title_gu, kicker, intro, intro_gu, body, renderer, sort_order, published) values ('phd-research', 'PhD & Research', 'પીએચ.ડી. અને સંશોધન', 'Folio V', 'Our research guides and the department''s booklets for readers at every stage.', 'અમારા સંશોધન માર્ગદર્શકો અને દરેક તબક્કાના વાચકો માટે વિભાગની પુસ્તિકાઓ.', '{}'::text[], 'research', 50, true)
