insert into public.sections (slug, title, title_gu, kicker, intro, intro_gu, body, renderer, sort_order, published) values ('results', 'Results', 'પરિણામ', 'Folio VI', 'Results links and our top achievers, published with their consent.', 'પરિણામની લિંક અને અમારા શ્રેષ્ઠ વિદ્યાર્થીઓ — તેમની સંમતિથી પ્રકાશિત.', '{}'::text[], 'results', 60, true)
