insert into public.sections (slug, title, title_gu, kicker, intro, intro_gu, body, renderer, sort_order, published) values ('helpdesk', 'Helpdesk', 'સહાય કેન્દ્ર', 'Folio VII', 'Raise a query with the department and track its status with your ticket reference.', 'વિભાગને તમારો પ્રશ્ન મોકલો અને ટિકિટ નંબરથી તેની સ્થિતિ જાણો.', '{}'::text[], 'helpdesk', 70, true)
