insert into public.sections (slug, title, title_gu, kicker, intro, intro_gu, body, renderer, sort_order, published) values ('events-gallery', 'Events & Gallery', 'કાર્યક્રમો અને ચિત્રસંગ્રહ', 'Folio VIII', 'Seminars, workshops, orientation programmes and literary events of the department.', 'વિભાગના પરિસંવાદો, કાર્યશાળાઓ, ઓરિએન્ટેશન કાર્યક્રમો અને સાહિત્યિક કાર્યક્રમો.', '{}'::text[], 'gallery', 80, false)
