insert into public.programs (id, code, title, level_group, level, duration, medium, eligibility, status, description, highlights, future_scope, sort_order, published) values ('bf380f5e-878e-57af-a0d5-a2d83a96dc12', 'BA-ENG', 'Bachelor of Arts — English (Major)', 'ba', 'Undergraduate · NEP 2020', '3 years (degree) · 4 years (Honours)', 'English', 'Higher Secondary (10+2) or equivalent, as per university norms.', 'Admissions as per university schedule', 'A four-year undergraduate programme under NEP 2020 with multiple entry and exit, moving from foundations of language and literary forms to British, American, Indian and world literatures, criticism and theory, with skill and value-added courses along the way.', array['Multiple entry and exit under NEP 2020', 'Indian Writing in English and translation studies', 'Honours year with research component']::text[], array['Postgraduate study in English and allied disciplines (M.A., B.Ed.)', 'Competitive examinations that test language and comprehension', 'Entry-level roles in content writing, editing and communication', 'Translation and language-support work', 'A strong base in reading, writing and critical thinking for any career']::text[], 10, true)
  on conflict (id) do update set code = excluded.code, title = excluded.title, level_group = excluded.level_group, level = excluded.level, duration = excluded.duration, medium = excluded.medium, eligibility = excluded.eligibility, status = excluded.status, description = excluded.description, highlights = excluded.highlights, future_scope = excluded.future_scope, sort_order = excluded.sort_order, published = excluded.published;
insert into public.programs (id, code, title, level_group, level, duration, medium, eligibility, status, description, highlights, future_scope, sort_order, published) values ('57dd7533-ae79-532a-a450-47d2616991b4', 'MA-ENG', 'Master of Arts — English', 'ma', 'Postgraduate · NEP 2020', '2 years (4 semesters); 1-year format for 4-year Honours graduates', 'English', 'Graduation in any discipline from a recognised university, as per university norms.', 'Admissions as per university schedule', 'A rigorous postgraduate programme spanning the history of English literature from Chaucer to the contemporary, literary criticism and theory, Indian and New Literatures in English, and research methodology — supported by SLM, SSLM video lectures and an answer-writing companion.', array['Prepares for UGC NET / GSET', 'New Literatures in English and Indian Knowledge Systems', 'SSLM video lectures, unit by unit']::text[], array['Eligibility to appear for UGC NET / GSET for Assistant Professorship and research fellowships, as per the respective notifications', 'Doctoral research (PhD) in English and related fields', 'Teaching English at school and college levels, subject to the required qualifications', 'Translation, editing, publishing and academic writing', 'Content, media and communication roles that value advanced language skills']::text[], 20, true)
  on conflict (id) do update set code = excluded.code, title = excluded.title, level_group = excluded.level_group, level = excluded.level, duration = excluded.duration, medium = excluded.medium, eligibility = excluded.eligibility, status = excluded.status, description = excluded.description, highlights = excluded.highlights, future_scope = excluded.future_scope, sort_order = excluded.sort_order, published = excluded.published;
