insert into public.pantheon (id, name, tradition, era, verse, verse_source, translation, iks_context, sort_order, published) values ('1e162438-a6f6-5f13-a3dc-9bfcc7260aec', 'Bharata Muni', 'Sanskrit · Nāṭyaśāstra', 'c. 2nd century BCE – 2nd century CE', 'vibhāvānubhāva-vyabhicāri-saṃyogād rasa-niṣpattiḥ', 'Nāṭyaśāstra, Chapter 6 — the Rasa-sūtra', 'Rasa is born from the union of the determinants, the consequents and the transitory emotional states.', 'The Nāṭyaśāstra is India''s foundational treatise on drama, music and dance. Its theory of rasa — aesthetic relish — describes how a spectator savours emotion through art rather than suffering it. Later thinkers such as Abhinavagupta refined it into a philosophy of aesthetic experience, and it is often read alongside Aristotle''s catharsis in comparative poetics.', 10, true)
  on conflict (id) do update set name = excluded.name, tradition = excluded.tradition, era = excluded.era, verse = excluded.verse, verse_source = excluded.verse_source, translation = excluded.translation, iks_context = excluded.iks_context, sort_order = excluded.sort_order, published = excluded.published;
insert into public.pantheon (id, name, tradition, era, verse, verse_source, translation, iks_context, sort_order, published) values ('3cb59396-893d-50c2-a2e4-27496bb099d9', 'Kālidāsa', 'Sanskrit · Kāvya', 'c. 4th–5th century CE', 'kaścit kāntāvirahaguruṇā svādhikārāt pramattaḥ', 'Meghadūta, verse 1 (opening line)', 'A certain yakṣa, negligent of his duty and weighed down by separation from his beloved…', 'Kālidāsa''s Meghadūta founded the dūta-kāvya (messenger poem) tradition: an exiled yakṣa sends a cloud across India to his wife. His Abhijñānaśākuntalam, translated by William Jones in 1789, became one of the first Indian works to move European readers, linking Sanskrit poetics with world literature.', 20, true)
  on conflict (id) do update set name = excluded.name, tradition = excluded.tradition, era = excluded.era, verse = excluded.verse, verse_source = excluded.verse_source, translation = excluded.translation, iks_context = excluded.iks_context, sort_order = excluded.sort_order, published = excluded.published;
insert into public.pantheon (id, name, tradition, era, verse, verse_source, translation, iks_context, sort_order, published) values ('2ab5c32c-0079-505e-a9f6-10f4352d0e54', 'Narsinh Mehta', 'Gujarati · Bhakti', '15th century', 'વૈષ્ણવ જન તો તેને કહીએ, જે પીડ પરાઈ જાણે રે', 'Vaiṣṇava Jana To — bhajan', 'Call that person a true Vaishnava who knows the pain of others.', 'Revered as the ādi-kavi (first poet) of Gujarati, Narsinh Mehta of Junagadh wrote bhakti poetry that placed compassion above ritual and caste. Vaiṣṇava Jana To became Mahatma Gandhi''s beloved prayer — a vernacular text that entered the moral vocabulary of modern India.', 30, true)
  on conflict (id) do update set name = excluded.name, tradition = excluded.tradition, era = excluded.era, verse = excluded.verse, verse_source = excluded.verse_source, translation = excluded.translation, iks_context = excluded.iks_context, sort_order = excluded.sort_order, published = excluded.published;
insert into public.pantheon (id, name, tradition, era, verse, verse_source, translation, iks_context, sort_order, published) values ('89dce0d5-5129-5af0-afb7-4a003ef4e1a7', 'William Shakespeare', 'English · Renaissance', '1564–1616', 'Shall I compare thee to a summer''s day?
Thou art more lovely and more temperate:', 'Sonnet 18', null, 'Shakespeare arrived in India through colonial education but was quickly made Indian: Parsi theatre staged him in Gujarati, Urdu and Hindi from the nineteenth century, and Indian cinema keeps adapting him. Reading him beside Kālidāsa invites comparative questions of genre, rasa and the role of the spectator.', 40, true)
  on conflict (id) do update set name = excluded.name, tradition = excluded.tradition, era = excluded.era, verse = excluded.verse, verse_source = excluded.verse_source, translation = excluded.translation, iks_context = excluded.iks_context, sort_order = excluded.sort_order, published = excluded.published;
insert into public.pantheon (id, name, tradition, era, verse, verse_source, translation, iks_context, sort_order, published) values ('d404104d-cb79-56f2-a3cf-12f321ee6eb2', 'Jane Austen', 'English · Novel', '1775–1817', 'It is a truth universally acknowledged, that a single man in possession of a good fortune, must be in want of a wife.', 'Pride and Prejudice (1813), opening sentence', null, 'Austen''s irony turns on manners, marriage and money. Indian readers recognise her world readily, as the adaptations Bride and Prejudice (2004) and Aisha (2010) show. Her sense of decorum invites comparison with aucitya — propriety — which the Sanskrit critic Kṣemendra made the life of poetry.', 50, true)
  on conflict (id) do update set name = excluded.name, tradition = excluded.tradition, era = excluded.era, verse = excluded.verse, verse_source = excluded.verse_source, translation = excluded.translation, iks_context = excluded.iks_context, sort_order = excluded.sort_order, published = excluded.published;
insert into public.pantheon (id, name, tradition, era, verse, verse_source, translation, iks_context, sort_order, published) values ('8d927645-a585-5d4b-aeb4-8ea3317de9f4', 'Toru Dutt', 'Indian English · Poetry', '1856–1877', 'Like a huge Python, winding round and round
The rugged trunk, indented deep with scars,', 'Our Casuarina Tree', null, 'One of the earliest Indian poets in English, Toru Dutt retold stories of Sītā, Sāvitrī and Prahlāda from the epics and Purāṇas in Ancient Ballads and Legends of Hindustan (1882), bringing Indian narrative traditions into English verse before she died at twenty-one.', 60, true)
  on conflict (id) do update set name = excluded.name, tradition = excluded.tradition, era = excluded.era, verse = excluded.verse, verse_source = excluded.verse_source, translation = excluded.translation, iks_context = excluded.iks_context, sort_order = excluded.sort_order, published = excluded.published;
insert into public.pantheon (id, name, tradition, era, verse, verse_source, translation, iks_context, sort_order, published) values ('2513065c-3669-5268-a86f-b1dcc3dcee2f', 'Rabindranath Tagore', 'Bengali · English', '1861–1941', 'Where the mind is without fear and the head is held high;
Where knowledge is free;', 'Gitanjali (1912), poem 35', null, 'Tagore, Nobel laureate in 1913, drew on the Upaniṣads, the Bāul singers and Vaiṣṇava poetry. At Śāntiniketan he revived the tapovana ideal of learning in open nature — a fitting forebear for open learning, where knowledge is meant to be free.', 70, true)
  on conflict (id) do update set name = excluded.name, tradition = excluded.tradition, era = excluded.era, verse = excluded.verse, verse_source = excluded.verse_source, translation = excluded.translation, iks_context = excluded.iks_context, sort_order = excluded.sort_order, published = excluded.published;
insert into public.pantheon (id, name, tradition, era, verse, verse_source, translation, iks_context, sort_order, published) values ('a10fe43f-bb60-5a13-a731-0222736be765', 'Raja Rao', 'Indian English · Novel', '1908–2006', null, 'Kanthapura (1938)', null, 'Kanthapura tells of the Gandhian movement in a South Indian village in the manner of a sthala-purāṇa, the legendary history of a place, narrated by a village grandmother as in harikathā. In his foreword Rao argued that Indians must write in English with their own rhythm and idiom — a manifesto for Indian English fiction.', 80, true)
  on conflict (id) do update set name = excluded.name, tradition = excluded.tradition, era = excluded.era, verse = excluded.verse, verse_source = excluded.verse_source, translation = excluded.translation, iks_context = excluded.iks_context, sort_order = excluded.sort_order, published = excluded.published;


