insert into public.knowledge_chunks (id, title, course_code, content, sort_order, published) values ('4d1fb105-1728-58df-a93d-75b6bcc2aa88', 'About the Department of English', null, 'The Department of English is part of the School of Humanities and Social Sciences (SHSS) at Dr. Babasaheb Ambedkar Open University (BAOU), Ahmedabad, Gujarat. It offers English programmes through open and distance learning (ODL) with Self-Learning Material (SLM), video lectures and the Smart SLM (SSLM) initiative. Faculty: Prof. (Dr.) Ami Upadhyay (Vice Chancellor and Head), Dr. Ankit Parmar, Dr. Yesha Bhatt, Dr. Bhavana Trivedi and Dr. Axansh Parmar (Assistant Professors).', 10, true)
  on conflict (id) do update set title = excluded.title, course_code = excluded.course_code, content = excluded.content, sort_order = excluded.sort_order, published = excluded.published;
insert into public.knowledge_chunks (id, title, course_code, content, sort_order, published) values ('abf62e5f-0936-52a8-a251-8f6efef0f89b', 'Programmes and eligibility', null, 'BA English (Major) under NEP 2020: 3-year degree or 4-year Honours; eligibility Higher Secondary (10+2) or equivalent as per university norms. MA English: 2 years (4 semesters), with a 1-year format for 4-year Honours graduates; eligibility graduation in any discipline from a recognised university, as per university norms. Admission schedules, fees and the online application are published on the university website (baou.edu.in); learners should always confirm current details there.', 20, true)
  on conflict (id) do update set title = excluded.title, course_code = excluded.course_code, content = excluded.content, sort_order = excluded.sort_order, published = excluded.published;
insert into public.knowledge_chunks (id, title, course_code, content, sort_order, published) values ('25f5a774-d33e-5ca0-abf2-3cb2d88eee09', 'Assignments and study material', null, 'Assignment booklets, syllabi and SSLM material are published in the Programmes section of this portal under Library, filtered by programme and category. Submission deadlines and instructions are given in each booklet and announced in the ticker and in Results & Notices. Learners with problems downloading or submitting assignments should raise a Helpdesk ticket with their enrolment number.', 30, true)
  on conflict (id) do update set title = excluded.title, course_code = excluded.course_code, content = excluded.content, sort_order = excluded.sort_order, published = excluded.published;
insert into public.knowledge_chunks (id, title, course_code, content, sort_order, published) values ('27fc6be2-aab2-52ee-a2e8-93e559045918', 'Helpdesk', null, 'The Helpdesk section lets learners raise a query about admission, assignments, examinations, results, study material, fees or other matters. Each query receives a ticket reference beginning with ENG. Learners can check the status and the department''s reply by entering the reference and the email address they used.', 40, true)
  on conflict (id) do update set title = excluded.title, course_code = excluded.course_code, content = excluded.content, sort_order = excluded.sort_order, published = excluded.published;
insert into public.knowledge_chunks (id, title, course_code, content, sort_order, published) values ('c0549a8a-811a-5ee1-ad1e-73471131905a', 'Paradise Lost Books I and II — overview', 'MEG-102', 'John Milton''s Paradise Lost (1667; 12 books in 1674) is an epic in blank verse whose stated aim is to justify the ways of God to men. Book I opens with the invocation to the Heavenly Muse, then shows Satan and the fallen angels on the burning lake of Hell; Satan rouses Beelzebub and the legions, declares that the mind is its own place, and the angels build Pandemonium. Book II presents the great consultation: Moloch urges open war, Belial counsels ignoble ease, Mammon proposes building a rival empire in Hell, and Beelzebub (voicing Satan''s plan) proposes corrupting God''s new creation, Man. Satan volunteers for the journey, meets Sin and Death at Hell''s gate, and crosses Chaos. Key debates for exams: Satan as heroic or self-deceiving (Blake, Shelley vs. C. S. Lewis), Milton''s grand style, epic conventions, and the political resonance of the council scene.', 50, true)
  on conflict (id) do update set title = excluded.title, course_code = excluded.course_code, content = excluded.content, sort_order = excluded.sort_order, published = excluded.published;
insert into public.knowledge_chunks (id, title, course_code, content, sort_order, published) values ('2d4b2da8-5720-5128-abf2-0f3b44694f88', 'New Literatures in English — introduction', 'MEG-202', 'New Literatures in English refers to writing in English from the former British colonies — Africa, the Caribbean, South Asia, Australia, New Zealand and Canada — that emerged mainly in the twentieth century. The term replaced ''Commonwealth literature'' and overlaps with postcolonial literature. Key concerns include the politics of using the coloniser''s language, the remaking of English with local idiom (Achebe, Raja Rao), hybridity and identity, the recovery of history and myth, and resistance to colonial representation.', 60, true)
  on conflict (id) do update set title = excluded.title, course_code = excluded.course_code, content = excluded.content, sort_order = excluded.sort_order, published = excluded.published;
insert into public.knowledge_chunks (id, title, course_code, content, sort_order, published) values ('87601240-f866-5b50-a3db-e6a568d6b9d0', 'Rasa theory', null, 'Rasa theory comes from Bharata Muni''s Nāṭyaśāstra. The rasa-sūtra states that rasa arises from the combination of vibhāva (determinants or causes), anubhāva (consequents, the outward expressions) and vyabhicāri bhāva (transitory states). Bharata lists eight rasas — śṛṅgāra (erotic/love), hāsya (comic), karuṇa (pathetic), raudra (furious), vīra (heroic), bhayānaka (terrible), bībhatsa (odious) and adbhuta (marvellous); later critics added śānta (peace). Abhinavagupta explained rasa as a universalised (sādhāraṇīkaraṇa) aesthetic relish experienced by the sahṛdaya, the sensitive spectator.', 70, true)
  on conflict (id) do update set title = excluded.title, course_code = excluded.course_code, content = excluded.content, sort_order = excluded.sort_order, published = excluded.published;

commit;
